def comb_sort(lst):
    shrink_factor = 1.3
    gap = len(lst)
    sorted_flag = False

    while not sorted_flag:
        gap = int(gap / shrink_factor)
        if gap <= 1:
            gap = 1
            sorted_flag = True

        i = 0
        while i + gap < len(lst):
            if lst[i] > lst[i + gap]:
                lst[i], lst[i + gap] = lst[i + gap], lst[i]
                sorted_flag = False
            i += 1

    return lst

