def common_in_nested_lists(nested_lists):
    if not nested_lists:
        return []

    # Start with the first list converted to a set
    common_set = set(nested_lists[0])

    # Intersect with each subsequent list
    for lst in nested_lists[1:]:
        common_set &= set(lst)

    return list(common_set)

