def max_product_tuple(tuples_list):
    max_prod = 0
    for i in range(len(tuples_list)):
        for j in range(i + 1, len(tuples_list)):
            t1 = tuples_list[i]
            t2 = tuples_list[j]
            # Calculate product of all combinations between the two tuples
            for a in t1:
                for b in t2:
                    prod = abs(a * b)
                    if prod > max_prod:
                        max_prod = prod
    return max_prod

