def amicable_numbers_sum(limit):
    def sum_divisors(n):
        if n <= 1:
            return 0
        div_sum = 1
        for i in range(2, int(n**0.5) + 1):
            if n % i == 0:
                div_sum += i
                if i != n // i:
                    div_sum += n // i
        return div_sum

    total = 0
    for num in range(1, limit + 1):
        partner = sum_divisors(num)
        if partner > num and sum_divisors(partner) == num:
            total += num + partner
    return total

