def sum(a, b):
    # Find the greatest common divisor
    def gcd(x, y):
        while y:
            x, y = y, x % y
        return x

    g = gcd(a, b)

    # Find all divisors of the GCD
    common_divisors = []
    for i in range(1, int(g**0.5) + 1):
        if g % i == 0:
            common_divisors.append(i)
            if i != g // i:
                common_divisors.append(g // i)

    return sum(common_divisors)

