def magic_square_test(matrix):
    n = len(matrix)
    if n == 0:
        return False

    # Check if all rows have the same length
    for row in matrix:
        if len(row) != n:
            return False

    # Calculate the target sum from the first row
    target_sum = sum(matrix[0])

    # Check each row sum
    for i in range(n):
        if sum(matrix[i]) != target_sum:
            return False

    # Check each column sum
    for j in range(n):
        col_sum = sum(matrix[i][j] for i in range(n))
        if col_sum != target_sum:
            return False

    # Check main diagonal sum
    diag1_sum = sum(matrix[i][i] for i in range(n))
    if diag1_sum != target_sum:
        return False

    # Check anti-diagonal sum
    diag2_sum = sum(matrix[i][n - 1 - i] for i in range(n))
    if diag2_sum != target_sum:
        return False

    return True

