def find_solution(a, b, n):
    # Extended Euclidean Algorithm to solve ax + by = gcd(a, b)
    def extended_gcd(a, b):
        if a == 0:
            return b, 0, 1
        else:
            g, x, y = extended_gcd(b % a, a)
            return g, y - (b // a) * x, x

    g, x0, y0 = extended_gcd(a, b)

    # Check if a solution exists
    if n % g != 0:
        return None

    # Scale the solution
    x = x0 * (n // g)
    y = y0 * (n // g)

    return (x, y)
