def max_sum(arr):
    if not arr:
        return 0

    n = len(arr)

    inc = [0] * n
    inc[0] = arr[0]

    for i in range(1, n):
        inc[i] = arr[i]
        for j in range(i):
            if arr[j] < arr[i]:
                inc[i] = max(inc[i], inc[j] + arr[i])

    dec = [0] * n
    dec[n - 1] = arr[n - 1]

    for i in range(n - 2, -1, -1):
        dec[i] = arr[i]
        for j in range(i + 1, n):
            if arr[j] < arr[i]:
                dec[i] = max(dec[i], dec[j] + arr[i])

    max_bitonic_sum = 0

    for i in range(n):
        current_sum = inc[i] + dec[i] - arr[i]
        if current_sum > max_bitonic_sum:
            max_bitonic_sum = current_sum

    return max_bitonic_sum

