def start_withp(words):
    result = []
    for word in words:
        # Split the string into individual words if it contains spaces
        parts = word.split()
        for part in parts:
            if part.startswith('p') or part.startswith('P'):
                result.append(part)
                if len(result) == 2:
                    return tuple(result)
