def max_sum_increasing_subseq(arr, n, i, k):
    if k >= n or i < 0 or k <= i:
        return 0

    dp = [0] * n

    for j in range(k):
        if j > i:
            continue

        dp[j] = arr[j]

        for prev in range(j):
            if prev > i:
                continue

            if arr[prev] < arr[j]:
                if dp[prev] + arr[j] > dp[j]:
                    dp[j] = dp[prev] + arr[j]

    max_prev_sum = 0
    found_valid = False

    for prev in range(i + 1):
        if arr[prev] < arr[k]:
            if dp[prev] > max_prev_sum:
                max_prev_sum = dp[prev]
                found_valid = True

    if found_valid:
        return max_prev_sum + arr[k]
    else:
        return arr[k]

