def set_left_most_unset_bit(n: int) -> int:
    if n < 0:
        raise ValueError("Input must be a non-negative integer")

    # Find the position of the leftmost unset bit
    # We need to find the highest bit position that is 0
    # Start from the most significant bit and go down

    # Get the number of bits needed to represent n
    if n == 0:
        return 1  # Leftmost unset bit of 0 (binary 0) is at position 0

    bit_length = n.bit_length()

    # Check each bit from the most significant to least significant
    for i in range(bit_length - 1, -1, -1):
        if not (n & (1 << i)):
            # Found the leftmost unset bit
            return n | (1 << i)

    # If all bits up to bit_length are set, we need to add a new bit
    return n | (1 << bit_length)

