def get_max_sum(n, memo=None):
    if memo is None:
        memo = {}

    if n in memo:
        return memo[n]

    if n == 0:
        return 0

    # Calculate the sum of recursive calls
    split_sum = get_max_sum(n // 2, memo) + get_max_sum(n // 3, memo) + get_max_sum(n // 4, memo) + get_max_sum(n // 5, memo)

    # Take the maximum of n and the split sum
    result = max(n, split_sum)

    memo[n] = result
    return result

