def max_product(arr):
    if not arr:
        return 0

    n = len(arr)
    # dp[i] will store the maximum product of an increasing subsequence ending at index i
    dp = [1] * n

    for i in range(1, n):
        for j in range(i):
            if arr[j] < arr[i]:
                if dp[j] * arr[i] > dp[i]:
                    dp[i] = dp[j] * arr[i]

    return max(dp)

