def tuple_intersection(list1, list2):
    # Convert each tuple in the lists to a frozenset to ignore order
    set1 = {frozenset(t) for t in list1}
    set2 = {frozenset(t) for t in list2}

    # Find intersection of these sets of frozensets
    common_frozensets = set1 & set2

    # Convert back to sorted tuples for consistent representation
    result = {tuple(sorted(fs)) for fs in common_frozensets}

    return result

