def extract_even(t):
    result = []
    for item in t:
        if isinstance(item, tuple):
            # Recursively process the nested tuple
            processed = extract_even(item)
            # Only include the nested tuple if it has at least one even element or is not empty after processing
            if processed:  # This checks if the resulting tuple is non-empty
                result.append(processed)
        elif isinstance(item, int):
            if item % 2 == 0:
                result.append(item)

    # Convert list back to tuple
    return tuple(result)

