def catalan_number(n):
    if n <= 1:
        return 1

    # Using the formula: C(n) = (2n)! / ((n+1)! * n!)
    # Or recursively: C(n) = sum(C(i) * C(n-1-i)) for i in 0..n-1
    # Or using dynamic programming

    dp = [0] * (n + 1)
    dp[0] = 1
    dp[1] = 1

    for i in range(2, n + 1):
        for j in range(i):
            dp[i] += dp[j] * dp[i - 1 - j]

    return dp[n]

