def maxAverageOfPath(matrix):
    n = len(matrix)
    dp = [[0] * n for _ in range(n)]
    dp[0][0] = matrix[0][0]

    for j in range(1, n):
        dp[0][j] = dp[0][j-1] + matrix[0][j]

    for i in range(1, n):
        dp[i][0] = dp[i-1][0] + matrix[i][0]

    for i in range(1, n):
        for j in range(1, n):
            previous_max = max(dp[i-1][j], dp[i][j-1])
            dp[i][j] = previous_max + matrix[i][j]

    max_sum = dp[n-1][n-1]
    num_cells = 2 * n - 1
    return max_sum / num_cells

