def is_polite(n):
    count = 0
    power_of_2 = 1
    result = n

    while True:
        temp = n + count

        new_count = 0
        p = 1

        while p <= temp:
            new_count += 1
            p *= 2

        if new_count == count:
            return temp
        else:
            count = new_count
            result = n + count

