def check_expression(expression):
    stack = []
    mapping = {')': '(', ']': '[', '}': '{'}

    for char in expression:
        if char in mapping.values():
            stack.append(char)
        elif char in mapping.keys():
            if not stack or stack.pop() != mapping[char]:
                return False

    return len(stack) == 0

