def find_combinations(tuples_list):
    result = []
    for i in range(len(tuples_list)):
        for j in range(i + 1, len(tuples_list)):
            t1 = tuples_list[i]
            t2 = tuples_list[j]
            sum1 = t1[0] + t2[0]
            sum2 = t1[1] + t2[1]
            result.append((sum1, sum2))
    return sorted(result)

